package com.drogaria.backend.controller;
import com.drogaria.backend.dto.LojaRequest; import com.drogaria.backend.entity.Loja; import com.drogaria.backend.service.LojaService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/loja") public class LojaController { private final LojaService s; public LojaController(LojaService s){this.s=s;} @GetMapping public List<Loja> listar(){return s.listar();} @GetMapping("/{id}") public Loja buscar(@PathVariable Integer id){return s.buscar(id);} @PostMapping public ResponseEntity<Loja> salvar(@Valid @RequestBody LojaRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.salvar(r));} @PutMapping("/{id}") public Loja atualizar(@PathVariable Integer id,@Valid @RequestBody LojaRequest r){return s.atualizar(id,r);} @DeleteMapping("/{id}") public ResponseEntity<Void> excluir(@PathVariable Integer id){s.excluir(id);return ResponseEntity.noContent().build();} }